<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {ApiError,type ApiClient} from '../api';
import {readParentChannel,type ParentChannel} from '../parent-channels';
import {readParentWeixinCatalog,type ParentWeixinCatalog} from '../parent-channel-bindings';
const props=defineProps<{client:ApiClient;allowed:boolean;rows:ParentChannel[];kind:0|1}>();
const emit=defineEmits<{close:[];done:[string];contextInvalid:[]}>();
const catalogs=ref<ParentWeixinCatalog[]>([]),selected=ref('0'),loading=ref(false),busy=ref(false),unknown=ref(false),error=ref(''),dialog=ref<HTMLElement>();
const title=computed(()=>props.kind===0?'批量关联微信公众号':'批量关联微信小程序');
const options=computed(()=>{const first=catalogs.value[0];if(!first)return [];const kind=props.kind===0?'web':'mini';return first.items.filter(x=>x.kind===kind&&catalogs.value.every(c=>c.items.some(p=>p.id===x.id&&p.appid===x.appid&&p.kind===x.kind&&p.revision===x.revision)))});
let active=true,epoch=0,controller:AbortController|undefined,originalClient=props.client,originalCSRF=props.client.csrfToken;
function context(){return active&&props.allowed&&originalClient===props.client&&originalCSRF===props.client.csrfToken}
function guard(){if(context())return true;emit('contextInvalid');return false}
async function load(){const n=++epoch,c=props.client,csrf=c.csrfToken;originalClient=c;originalCSRF=csrf;controller?.abort();controller=new AbortController();catalogs.value=[];error.value='';loading.value=true;
 try{if(props.rows.length<1||props.rows.length>100||new Set(props.rows.map(r=>r.id)).size!==props.rows.length||props.rows.some(r=>!r.configured||r.pay_type!=='wxpay'||!r.fingerprint||!r.source_channel_id))throw new Error('请选择原微信支付通道');const result=await Promise.all(props.rows.map(async row=>readParentWeixinCatalog(await c.request('/payment-channels/'+row.id+'/weixin-options',{signal:controller!.signal}),row.id,row.source_channel_id!)));if(n!==epoch||!context())return;catalogs.value=result}catch(e){if(n===epoch&&context())error.value=e instanceof Error?e.message:'关联列表加载失败'}finally{if(n===epoch&&context())loading.value=false}}
async function save(){if(!guard()||loading.value||busy.value||unknown.value||catalogs.value.length!==props.rows.length)return;if(selected.value!=='0'&&!options.value.some(x=>x.id===selected.value)){error.value='请重新选择共同可用的微信应用';return}const n=epoch,c=props.client,csrf=c.csrfToken;busy.value=true;error.value='';
 try{const raw=await c.request('/payment-channels/bind-weixin',{method:'POST',body:{type:props.kind,weixin:selected.value,items:props.rows.map((row,i)=>({id:row.id,expected_fingerprint:row.fingerprint,expected_bindings_fingerprint:catalogs.value[i].fingerprint}))}});if(n!==epoch||!context()||csrf!==c.csrfToken)return;const v=raw as {type?:unknown;weixin?:unknown;items?:unknown;total?:unknown};if(v.type!==props.kind||v.weixin!==selected.value||!Array.isArray(v.items)||v.items.length!==props.rows.length||v.total!==props.rows.length)throw new Error('批量关联结果无法核实');const rows=v.items.map(readParentChannel);if(new Set(rows.map(r=>r.id)).size!==props.rows.length||rows.some(r=>!props.rows.some(old=>old.id===r.id)||(props.kind===0?r.account?.appwxmp||'0':r.account?.appwxa||'0')!==selected.value))throw new Error('返回关联与原目标不一致');emit('done','微信应用批量关联已保存')}catch(e){if(n===epoch&&context()){unknown.value=!(e instanceof ApiError&&e.responseDecoded&&e.status>=400&&e.status<500);error.value=unknown.value?'结果未知，请读取原目标核对，勿重复提交。':e instanceof Error?e.message:'批量关联失败'}}finally{if(n===epoch&&context())busy.value=false}}
async function readOriginal(){if(!guard()||busy.value||!unknown.value)return;const n=epoch;busy.value=true;try{const rows=await Promise.all(props.rows.map(async row=>{const out=readParentChannel(await props.client.request('/payment-channels/'+row.id));if(out.id!==row.id||!out.configured)throw new Error('原通道无法核实');return out}));if(n!==epoch||!context())return;emit('done','已读取原 '+rows.length+' 个通道，请核对当前关联。')}catch(e){if(n===epoch&&context())error.value='原目标仍无法核实，请稍后读取，勿重复提交。'}finally{if(n===epoch&&context())busy.value=false}}
function close(){if(!guard()||busy.value||unknown.value)return;emit('close')}
function trap(e:KeyboardEvent){if(e.key!=='Tab')return;const nodes=dialog.value?.querySelectorAll<HTMLElement>('button:not([disabled]),select:not([disabled])');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
watch(()=>[props.client,props.client.csrfToken,props.allowed],()=>{if(!context())emit('contextInvalid')},{flush:'sync'});
onMounted(async()=>{await load();await nextTick();dialog.value?.focus()});onBeforeUnmount(()=>{active=false;++epoch;controller?.abort();catalogs.value=[];selected.value='0'});
</script>
<template><div class="modal-backdrop"><section ref="dialog" tabindex="-1" role="dialog" aria-modal="true" :aria-label="title" class="modal panel binding-batch" @keydown="trap" @keydown.esc.prevent="close"><div class="toolbar"><h3>{{title}}</h3><button type="button" class="pa-icon-btn pa-icon-btn--ghost" aria-label="关闭" :disabled="busy||unknown" @click="close">×</button></div><p>以下通道将同时更新，任一原版本变化会拒绝整批。</p><ul><li v-for="row in rows" :key="row.id">#{{row.id}} {{row.name}}</li></ul><label>关联应用<select v-model="selected" aria-label="批量微信应用" :disabled="loading||busy||unknown||!catalogs.length"><option value="0">取消关联</option><option v-for="app in options" :key="app.id" :value="app.id">#{{app.id}}（{{app.appid}}）</option></select></label><p v-if="!loading&&!error&&!options.length" class="muted">所选通道没有共同可用的微信应用，可取消原关联。</p><p v-if="loading" role="status">正在加载原通道应用…</p><p v-if="error" role="alert">{{error}}</p><div class="toolbar-actions"><button type="button" class="pa-btn" :disabled="busy||unknown" @click="close">取消</button><button v-if="unknown" type="button" class="pa-btn pa-btn--primary" :disabled="busy" @click="readOriginal">读取原目标</button><button v-else data-weixin-batch-confirm type="button" class="pa-btn pa-btn--primary" :disabled="busy||loading||catalogs.length!==rows.length" @click="save">确定</button></div></section></div></template>
<style scoped>.binding-batch{width:min(100%,560px);overflow-wrap:anywhere}.binding-batch .toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px}.binding-batch label{display:grid;gap:6px;margin:0}.binding-batch select{min-width:0;max-width:100%}</style>
